from fractions import Fraction as Q
Z=(Q(0),)*4;O=(Q(1),Q(0),Q(0),Q(0));S=(Q(0),Q(1),Q(0),Q(0));I=(Q(0),Q(0),Q(1),Q(0))
def a(x,y):return tuple(x[k]+y[k]for k in range(4))
def s(q,x):return tuple(q*z for z in x)
def n(x):return s(-1,x)
def c(x):return(x[0],x[1],-x[2],-x[3])
def m(x,y):
 A,B,C,D=x;E,F,G,H=y
 return(A*E+3*B*F-C*G-3*D*H,A*F+B*E-C*H-D*G,A*G+3*B*H+C*E+3*D*F,A*H+B*G+C*F+D*E)
def sm(xs):
 z=Z
 for x in xs:z=a(z,x)
 return z
def mm(A,B):return[[sm(m(A[i][k],B[k][j])for k in range(len(B)))for j in range(len(B[0]))]for i in range(len(A))]
def dg(A):return[[c(A[j][i])for j in range(len(A))]for i in range(len(A[0]))]
def kr(A,B):return[[m(A[i//len(B)][j//len(B[0])],B[i%len(B)][j%len(B[0])])for j in range(len(A[0])*len(B[0]))]for i in range(len(A)*len(B))]
ID=[[O,Z],[Z,O]];EA=[[O],[Z],[Z],[O]];EB=[[Z],[O],[n(O)],[Z]];JB=[[O,Z],[Z,n(O)]]
Wg=[[a(n(S),I),Z],[Z,s(-2,I)],[a(O,m(I,S)),Z],[Z,s(2,O)]];Wh=[[c(x)for x in row]for row in Wg];ag=s(Q(1,2),a(n(S),n(I)));ah=c(ag)
Ug=[[m(ag,x)for x in row]for row in Wg];Uh=[[m(ah,x)for x in row]for row in Wh]
LA=kr(EA,ID);LB=mm(kr(EB,ID),JB);RG=mm(kr(ID,Ug),Uh);RH=mm(kr(ID,Uh),Ug)
E=[[s(8,O),s(8,O)],[s(-8,I),s(8,I)]]
for p,L in enumerate((LA,LB)):
 for q,R in enumerate((RG,RH)):
  M=mm(dg(L),R);assert M==[[E[p][q],Z],[Z,E[p][q]]]
assert mm(dg(LA),LA)==[[s(2,O),Z],[Z,s(2,O)]] and mm(dg(LB),LB)==[[s(2,O),Z],[Z,s(2,O)]]
assert mm(dg(RG),RG)==[[s(64,O),Z],[Z,s(64,O)]] and mm(dg(RH),RH)==[[s(64,O),Z],[Z,s(64,O)]]
print({'field':'Q(sqrt(3),i)','cleared_overlap_scalars':[['8','8'],['-8i','8i']],'normalized_F':'1/sqrt(2) [[1,1],[-i,i]]','exact_path_grams':True,'exact_unitarity':True})
